// (TestField): the user's messages "X is required" / "X must be …"
func (t *GenJournalLine) TestField(fieldName string, value ...any) error {
	no := t.FieldNo(fieldName)
	current, ok := t.FieldValue(no)
	if !ok {
		// a FlowField: its value as CalcFields left it (classic TESTFIELD after CALCFIELDS)
		current, ok = t.flowFieldValue(no)
	}
	if !ok {
		return fmt.Errorf("TestField: %s is not a field of Gen_Journal_Line", fieldName)
	}
	field := t.FieldName(no)
	if len(value) == 0 {
		if tables.IsEmptyValue(current) {
			return apperrors.FieldRequired(GenJournalLineTableName, field)
		}
		return nil
	}
	if !tables.SameValue(current, value[0]) {
		return apperrors.FieldMustBeValue(GenJournalLineTableName, field, value[0])
	}
	return nil
}

